layer.css:
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(2, 128, 125); border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgba(2, 128, 125, 0.5); text-decoration-thickness: 1px; text-underline-offset: 2px; transition: text-decoration-color 0.15s ease-in-out }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: system-ui, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 22px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-color: rgb(2 128 125) }
